-- Production unique indexes the Drizzle schema does not declare (30 of 64 on
-- 2026-11-23; schema-base.ts lists several as raw sql strings, which
-- drizzle-kit push ignores). Code relies on them: ON CONFLICT targets, the
-- inbound SMS and consent replay dedupes. Without them the lane would test a
-- weaker database than production.
DO $$ BEGIN IF to_regclass('public.wireline_accounts') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS idx_accounts_user_type ON public.wireline_accounts USING btree (user_id, type); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_agent_team_members') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_team_members_team_agent ON public.wireline_agent_team_members USING btree (team_id, agent_id); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_cadence_runs') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS idx_cadence_runs_lead_unique ON public.wireline_cadence_runs USING btree (lead_id, cadence_id) WHERE (status = 'active'::text); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_checkout_operations') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_checkout_operations_active_user ON public.wireline_checkout_operations USING btree (user_id) WHERE (status = ANY (ARRAY['creating'::text, 'open'::text])); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_checkout_operations') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_checkout_operations_stripe_session ON public.wireline_checkout_operations USING btree (stripe_checkout_session_id) WHERE (stripe_checkout_session_id IS NOT NULL); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_consent_log') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_consent_log_call_ai_disclosure ON public.wireline_consent_log USING btree (user_id, call_id) WHERE ((call_id IS NOT NULL) AND (event = ANY (ARRAY['ai_disclosure_played'::text, 'ai_disclosure_not_detected'::text, 'ai_disclosure_unverifiable'::text]))); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_consent_log') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_consent_log_call_disclosure ON public.wireline_consent_log USING btree (user_id, call_id) WHERE ((call_id IS NOT NULL) AND (event = ANY (ARRAY['disclosure_played'::text, 'disclosure_not_detected'::text, 'disclosure_unverifiable'::text]))); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_consent_log') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_consent_log_call_opt_out ON public.wireline_consent_log USING btree (user_id, call_id) WHERE ((call_id IS NOT NULL) AND (event = 'opt_out_requested'::text)); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_consent_log') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_consent_log_twilio_message_sid ON public.wireline_consent_log USING btree (user_id, ((metadata ->> 'twilio_message_sid'::text))) WHERE (NULLIF((metadata ->> 'twilio_message_sid'::text), ''::text) IS NOT NULL); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_credit_ledger') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS wireline_credit_ledger_idempotency_key ON public.wireline_credit_ledger USING btree (user_id, idempotency_key) WHERE (idempotency_key IS NOT NULL); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_dnc_list') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS wireline_dnc_list_user_phone_unique ON public.wireline_dnc_list USING btree (user_id, phone); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.wireline_email_messages') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_email_messages_user_google_message ON public.wireline_email_messages USING btree (user_id, google_message_id); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
