DO $$ BEGIN IF to_regclass('public.wireline_spend_alerts') IS NOT NULL THEN BEGIN CREATE UNIQUE INDEX IF NOT EXISTS uq_spend_alerts_user_period_threshold ON public.wireline_spend_alerts USING btree (user_id, period, threshold_pct); EXCEPTION WHEN undefined_column OR duplicate_table OR duplicate_object THEN NULL; END; END IF; END $$;
